#!/usr/bin/env python3
"""Assemble research/DIFF-2026-10-to-2026-11.md from the generated parts in
research/diff-2026-10-to-2026-11/ (files.md, amendments/*, etat_b.md, workbooks.md, pages.md)
and the hand-written analysis below.  Re-run after regenerating the parts:

  python3 -I scripts/liasses_parse.py data/raw research/diff-2026-10-to-2026-11/amendments_old.json
  python3 -I scripts/liasses_parse.py data/raw-2026-11-21 research/diff-2026-10-to-2026-11/amendments_new.json
  python3 -I scripts/diff_liasses.py  .../amendments_old.json .../amendments_new.json research/diff-2026-10-to-2026-11/amendments
  python3 -I scripts/diff_etat_b.py   .../amendments_old.json .../amendments_new.json research/diff-2026-10-to-2026-11/etat_b.md
  python3 -I scripts/diff_workbooks.py . research/diff-2026-10-to-2026-11/workbooks.md
  python3 -I scripts/diff_pages.py . research/diff-2026-10-to-2026-11/pages.md
  python3 -I scripts/diff_files.py data/raw data/raw-2026-11-21 research/diff-2026-10-to-2026-11/files.md
  python3 -I scripts/build_diff_report.py .
"""
import sys, os, re, json

root = sys.argv[1]
D = os.path.join(root, "research/diff-2026-10-to-2026-11")
OUT = os.path.join(root, "research/DIFF-2026-10-to-2026-11.md")


def rd(p):
    return open(os.path.join(D, p), encoding="utf-8").read()


def embed(p, shift=2, skip_until=None, stop_at=None, number_prefix=None):
    """Include a generated markdown file, demoting its headings by `shift` levels and dropping its H1."""
    t = rd(p)
    if skip_until:
        t = t[t.index(skip_until):]
    if stop_at and stop_at in t:
        t = t[: t.index(stop_at)]
    out, in_code = [], False
    for ln in t.split("\n"):
        if ln.startswith("# ") and not out:
            continue
        m = re.match(r"^(#{1,6}) (.*)$", ln)
        if m and not in_code:
            title = m.group(2)
            if number_prefix and len(m.group(1)) == 2:
                title = re.sub(r"^(\d+)\. ", lambda mm: f"{number_prefix}{mm.group(1)} ", title)
            ln = "#" * min(6, len(m.group(1)) + shift) + " " + title
        out.append(ln)
    return "\n".join(out).strip() + "\n"


idx = json.load(open(os.path.join(D, "amendments/amendments_index.json"), encoding="utf-8"))
LAB = {"Liasse_PLF_P1": "PLF-P1", "Liasse_PLF_P2": "PLF-P2", "Liasse_PLFSS": "PLFSS"}
WHAT = {
    ("PLF-P1", 1): "II.5 gains « sont instituées par la présente loi pour l’aide fondamentale et » and the modulation « à raison de l’âge, du handicap ou, à titre transitoire, du bénéfice d’une pension de retraite servie par un régime obligatoire » ; IV.B list « 195° et 196°, 198° et 199° » → « 195° à 199° » (197° moves in) and IV.E list loses « 197°, » ; exposé wording (2 hunks)",
    ("PLF-P1", 10): "exposé only: + « Un amendement distinct propose de neutraliser l’ensemble des dépenses fiscales par une clause générale ; les deux ne se cumulent pas. »",
    ("PLF-P1", 11): "dispositif II « exercices ouverts » → « exercices clos » (1er janvier 2027) ; exposé: + options-cessation sentence, « dû au titre des exercices clos en 2027 », + cross-reference sentence",
    ("PLF-P1", 12): "dispositif II and exposé (twice): « 1er juillet 2027 » → « 1er janvier 2027 » ; + cross-reference sentence",
    ("PLF-P1", 13): "exposé only: + cross-reference sentence (clause générale)",
    ("PLF-P1", 14): "exposé only: + cross-reference sentence (clause générale)",
    ("PLF-P1", 15): "exposé only: + cross-reference sentence (clause générale)",
    ("PLF-P1", 22): "title « vingt et une » → « cinquante-quatre » ; dispositif: new I 4°-6° (CGI articles 235 ter ZG, 302 bis N … 1635 bis AH, two laws, CIBS L. 421-93 to L. 455-56 ranges), new I bis (accise sur l’électricité), I ter, II 3°-4°, III.A additions ; exposé rewritten (15 hunks)",
    ("PLF-P1", 23): "dispositif: new III (Caisse des dépôts passible de l’IS ; L. 518-16 CMF), IV-VI renumbered; exposé: + CDC sentence",
    ("PLF-P1", 25): "title « cinquante-sept » → « soixante-douze » ; dispositif: +15 abrogations (I 8° extended, new 10°-18°), 2027 last-year derogation for three taxes ; exposé: list of taxes extended",
    ("PLF-P1", 28): "pension supplement « majoré » → « minoré » (+ prorata rule, « régime obligatoire ») ; exposé follows",
    ("PLF-P1", 29): "new III bis (20 further local taxes abrogated), V derogation dates (1er juillet 2027 / 1er janvier 2028), VIII compensation of the local losses by the DGF ; exposé: + paragraph listing the 20 taxes",
    ("PLF-P2", 26): "II.C duration brackets 1-7 years → 24 months + 1 month per quarter of service (cap 84 months, cap by date of pension without décote), III.D end of service, new III.F ; exposé rewritten (~1 040 words changed)",
    ("PLF-P2", 33): "dispositif II and exposé: « 1er janvier 2027 » → « 1er avril 2027 »",
    ("PLF-P2", 34): "dispositif unchanged; exposé: programme « Service public de l’énergie » (10 749 607 515 €) → « Énergie, climat et après-mines » (1 251 260 465 €) ; 2027 saving « 600 millions » → « 300 millions d’euros, pour 600 millions d’euros en année pleine »",
}


def what(lid, n, r):
    if (lid, n) in WHAT:
        return WHAT[(lid, n)]
    if lid == "PLF-P2" and r["status"] == "CHANGED" and n <= 22:
        return f"état B: TOTAUX {r.get('etat_b_totaux_old', '')} → {r.get('etat_b_totaux_new', '')}; exposé rewritten (base AE, « retire », effect dates)"
    return ""


rows = []
for L in ("Liasse_PLF_P1", "Liasse_PLF_P2", "Liasse_PLFSS"):
    for k in sorted(idx[L], key=int):
        r = idx[L][k]
        lid = LAB[L]
        pg = r["pdf_pages_new"]
        pgs = "—" if not pg else (f"{pg[0]}" if pg[0] == pg[1] else f"{pg[0]}–{pg[1]}")
        po = r["pdf_pages_old"]
        pos = "—" if not po else (f"{po[0]}" if po[0] == po[1] else f"{po[0]}–{po[1]}")
        title = (r["title_new"] or r["title_old"]).replace("|", "\\|")
        if r["title_old"] and r["title_new"] and r["title_old"] != r["title_new"]:
            title += f" *(was: {r['title_old'].replace('|', chr(92) + '|')})*"
        rows.append(f"| {lid} | {r['new_n'] if r['new_n'] else '—'} | {r['old_n'] if r['old_n'] else '— (new)'} | {title} | {r['status']} | {pgs} | {pos} | {what(lid, int(k), r)} |")
table84 = "\n".join(rows)

