PAGES_HEAD = "\n---\n\n## 5. Fiches, manifeste and site pages (text diff)\n\n"


def main():
    parts = [HEAD, FOCUS]
    # 3.4 diffs
    parts.append("### 3.4 Word-level diff of every changed or new amendment\n\nOne block per amendment (unchanged ones are listed in § 3.2 only). The generated files `research/diff-2026-10-to-2026-11/amendments/Liasse_*.md` contain the same text with an entry for **every** amendment, including `UNCHANGED` ones. For the 22 état B amendments the credit tables are not word-diffed here (cells are compared in § 3.7 and `etat_b.md`); their exposé diffs are.\n")
    for L, lab, app in (("Liasse_PLF_P1", "PLF-P1", "A"), ("Liasse_PLF_P2", "PLF-P2", "B"), ("Liasse_PLFSS", "PLFSS", "C")):
        t = rd(f"amendments/{L}.md")
        secs = re.split(r"\n(?=## n° )", t)
        keep = []
        for s in secs[1:]:
            if "**Status**: UNCHANGED" in s:
                continue
            keep.append(s)
        parts.append(f"\n#### Appendix {app} — {lab}: {len(keep)} changed/new amendments\n\n" + "\n".join("#" * 1 + s if False else s.replace("## n° ", f"##### {lab} n° ", 1) for s in keep))
    parts.append(TAIL_SECTIONS)
    parts.append("### 3.7 État B: totals and mission by mission\n\n" + embed("etat_b.md", shift=2, stop_at="## 4. Programme lines", number_prefix="3.7.") + "\nProgramme-level lines (old → new, with « dont titre 2 » and each mission's old/new effect sentences) for the 23 missions: `research/diff-2026-10-to-2026-11/etat_b.md` § 4 and `data/derived-2026-11-21/etat_b_credits_retires_plf2027.csv`. Source numbers of the exposé « Il porte sur N programmes » count programme lines **without** the « dont titre 2 » sub-lines.\n")
    parts.append(HEAD_WB + WB_NOTE + "\n" + embed("workbooks.md", shift=1, number_prefix="4."))
    parts.append(PAGES_HEAD + embed("pages.md", shift=1, number_prefix="5."))
    parts.append("\n---\n" + DOWN)
    parts.append("\n---\n" + VERIF)
    open(OUT, "w", encoding="utf-8").write("\n".join(parts) + "\n")
    print("written", OUT, os.path.getsize(OUT), "bytes")


main()
